import { Routes, Route, Link } from 'react-router-dom';
import Pagina2 from './Paginas/Pagina2';
import { useNavigate } from 'react-router-dom';
import React, { useState } from 'react';



function HomePage() {
  const navigate = useNavigate();


  // --- NEW STATE VARIABLES ---
  const [username, setUsername] = useState(''); // State for the username input
  const [password, setPassword] = useState(''); // State for the password input
  const [error, setError] = useState('');     // State for the error message

  return (
     <div>
    <h1>Login Page</h1>
    <form onSubmit={handleLogin}>
      <div>
        <label>Username: </label>
        <input
          type="text"
          placeholder="Enter username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
      </div>
      <div>
        <label>Password: </label>
        <input
          type="password"
          placeholder="Enter password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
      </div>
      <button type="submit">Login</button>
    </form>
    {error && <p style={{ color: 'red' }}>{error}</p>}
  </div>
  );
  function handleLogin(event) {
  event.preventDefault(); // IMPORTANT: Prevents the default form submission which reloads the page

  // Clear any previous errors
  setError('');

  // --- This is our simple validation ---
  // In a real app, you would check this against a server
  if (username === 'user' && password === 'password123') {
    // If correct, navigate to the about page
    console.log('Login successful!');
    navigate('/about');
  } else {
    // If incorrect, set an error message
    setError('Invalid username or password. Please try again.');
  }
}
}
function App() {
  return (
    <div>
      {}
      <nav>
        <Link to="/">Pagina1</Link> | <Link to="/Pagina2">Pagina2</Link>
      </nav>

      <hr /> {}

      {}
      <Routes>
        <Route path="/" element={<HomePage/>} />
        <Route path="/Pagina2" element={<Pagina2/>} />
      </Routes>
    </div>
  );
}

export default App;
